CREATE EXTERNAL DATA SOURCE IF NOT EXISTS `src` WITH (SOURCE_TYPE = "ObjectStorage", LOCATION = "https://s3", AUTH_METHOD = "AWS", AWS_ACCESS_KEY_ID_SECRET_NAME = "a", aws_secret_access_key_secret_name = "b", AWS_REGION = "x");
CREATE OR REPLACE EXTERNAL DATA SOURCE `dir/src2` WITH (SOURCE_TYPE = "PostgreSQL", AUTH_METHOD = "BASIC", LOGIN = "u", PASSWORD_SECRET_NAME = "p");
CREATE EXTERNAL DATA SOURCE src3 WITH (SOURCE_TYPE = "PostgreSQL", AUTH_METHOD = "BASIC", LOGIN = "u", PASSWORD_SECRET_PATH = "/local/p");
CREATE EXTERNAL DATA SOURCE;
DROP EXTERNAL DATA SOURCE src3;
DROP EXTERNAL TABLE `et`;
CREATE OR REPLACE EXTERNAL TABLE `et` (a Utf8) WITH (DATA_SOURCE = "src", LOCATION = "/x", FORMAT = "csv_with_names");
